-- A store's product, the target of import.csv (D30). A store knows a product by
-- its own sku, never by our id, so (userId, sku) is what an import matches on.
-- The id is generated by the database because the import writes with one
-- INSERT … ON CONFLICT per batch, not through Prisma's client.

-- CreateTable
CREATE TABLE "Product" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "userId" UUID NOT NULL,
    "sku" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "priceCents" INTEGER NOT NULL,
    "currency" TEXT NOT NULL,
    "imageUrl" TEXT,
    "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "Product_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
-- What makes a replayed batch harmless: the same sku for the same store is an
-- update, never a second row. Per store, because two stores' "A-1" are
-- unrelated products.
CREATE UNIQUE INDEX "Product_userId_sku_key" ON "Product"("userId", "sku");

-- AddForeignKey
ALTER TABLE "Product" ADD CONSTRAINT "Product_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Hand-written: Prisma's schema language cannot express CHECK constraints. The
-- import validates every row first; these are the floor a bug in that
-- validation still cannot go below.
ALTER TABLE "Product" ADD CONSTRAINT "Product_sku_not_blank"
  CHECK (btrim("sku") <> '');

ALTER TABLE "Product" ADD CONSTRAINT "Product_name_not_blank"
  CHECK (btrim("name") <> '');

ALTER TABLE "Product" ADD CONSTRAINT "Product_priceCents_not_negative"
  CHECK ("priceCents" >= 0);

ALTER TABLE "Product" ADD CONSTRAINT "Product_currency_iso4217"
  CHECK ("currency" ~ '^[A-Z]{3}$');
